'use strict';

const { expect } = require('chai');
const crypto = require('crypto');
const util = require('util');
const sjcl = require('../lib/vendor/sjcl'); // base58 codec lives only in the vendored build

const KeyPair = require('../lib/keypair');
const keystore = require('../lib/keystore');
const { SIGN_TYPE } = require('../lib/constants');

// A real, pre-existing keystore generated by the old (oversized IV/salt) code
// path -- used to prove the fix does not require rotating already-issued
// keystores. aesctr_iv is 128 hex chars (64 bytes); scrypt_params.salt is
// 256 hex chars (128 bytes). Known plaintext: 'privbxgNEmueqwyqbbdJsVEwAs9bYyN9pqEmthVA7QZeAGe8jbhMHVRD'.
const OLD_FORMAT_KEYSTORE = {
  cypher_text: 'VTJGc2RHVmtYMTgzTDFBRFpTQ2lIUmJEaW1GandOK2o3UUpxNEticmdSN1gxMFhOWXdoWmk4dk5aWjd3TGpQODdNeXRaL0pMV3oxOS9UQ2grRzlGbVl4OTFmQ1V0Witq',
  aesctr_iv: '4296bb17e8bc3dc62cccc5425d9681a0d2a9f4eca7a2293aef312ecc7267fe99b6ef76fa60d34adf9038bb7801993052b02112a4e2846493e3ce8e6f9619cd7c',
  scrypt_params: {
    n: 16384,
    p: 1,
    r: 8,
    salt: 'b415cec9d465da52c7966cebf2c2a4141999c20d8bc25b13ac3b63c494173817828a57bc2ac09709dbeb46b2182ffd8b5c069ff6401c8d823eedbfedeb1478d1de28fdaa3f42293d2a90e01c8c16756dd6a9a69d9af1dfc867ecf8054a80aa45a6aa53790be3c20d07f50efe506b82e5c5efb29bbe6aa2aa801eb66cbf848508',
  },
  version: 2,
};
const OLD_FORMAT_PLAINTEXT = 'privbxgNEmueqwyqbbdJsVEwAs9bYyN9pqEmthVA7QZeAGe8jbhMHVRD';

describe('parsePrivateKey error messages do not leak the private key', function() {
  const validKey = new KeyPair('ed25519').getEncPrivateKey();

  function decode(enc) {
    return sjcl.codec.base58.decode(enc);
  }
  function encode(bits) {
    return sjcl.codec.base58.encode(bits);
  }

  function sha256(bytes) {
    return Array.from(crypto.createHash('sha256').update(Buffer.from(bytes)).digest());
  }
  function buildKeyWithRawLength(rawBytesArr) {
    const nvec = [0xda, 0x37, 0x9f, SIGN_TYPE.ed25519, ...rawBytesArr, 0x00];
    const checksum = sha256(sha256(nvec)).slice(0, 4);
    return encode([...nvec, ...checksum]);
  }

  function toHex(bytes) {
    return bytes.map((b) => (b & 0xff).toString(16).padStart(2, '0')).join('');
  }

  // A template literal interpolating a raw byte array implicitly calls its
  // .join(',') (Array#toString), producing a comma-separated decimal list --
  // a distinct encoding from hex, so it must be checked separately.
  function toDecimalList(bytes) {
    return bytes.map((b) => b & 0xff).join(',');
  }

  // Checks the raw base58 input AND any hex or decimal re-encoding of its
  // decoded bytes (whole key or just the payload) -- a mutant that leaks the
  // key via a different encoding than the original argument must still be
  // caught. Checks util.inspect(thrown), not just thrown.message: a mutant
  // that attaches the key as an extra property on the thrown Error (rather
  // than putting it in the message) would pass a message-only check but
  // still shows up in util.inspect/console.log output of the error.
  function assertNoLeak(badKey, expectedMessageSubstring) {
    const decoded = decode(badKey);
    const len = decoded.length;
    const payload = decoded.slice(4, Math.max(4, len - 5));
    const withoutChecksum = decoded.slice(0, Math.max(0, len - 4));
    const payloadHex = toHex(payload);
    const withoutChecksumHex = toHex(withoutChecksum);
    const payloadDecimal = toDecimalList(payload);
    const withoutChecksumDecimal = toDecimalList(withoutChecksum);

    let thrown;
    try {
      KeyPair.parsePrivateKey(badKey);
    } catch (e) {
      thrown = e;
    }
    expect(thrown, 'expected parsePrivateKey to throw').to.exist;
    expect(thrown.message).to.include(expectedMessageSubstring);

    // showHidden: a secret attached as a non-enumerable property (e.g. via
    // Object.defineProperty(err, 'k', { value: secret, enumerable: false }))
    // is invisible to a plain util.inspect() call otherwise.
    const inspected = util.inspect(thrown, { showHidden: true }).toLowerCase();
    expect(inspected).to.not.include(badKey.toLowerCase());
    if (payloadHex) expect(inspected).to.not.include(payloadHex);
    if (withoutChecksumHex) expect(inspected).to.not.include(withoutChecksumHex);
    if (payloadDecimal) expect(inspected).to.not.include(payloadDecimal);
    if (withoutChecksumDecimal) expect(inspected).to.not.include(withoutChecksumDecimal);
  }

  it('header-wrong branch does not leak the input key', function() {
    const bits = decode(validKey);
    bits[0] ^= 0xff;
    assertNoLeak(encode(bits), 'header is wrong');
  });

  it('type-wrong branch does not leak the input key', function() {
    const bits = decode(validKey);
    bits[3] = 0xaa; // not in VALID_SIGN_TYPES
    assertNoLeak(encode(bits), 'type is wrong');
  });

  it('compression-bit-wrong branch does not leak the input key', function() {
    const bits = decode(validKey);
    bits[bits.length - 5] ^= 0xff;
    assertNoLeak(encode(bits), 'compression bit is wrong');
  });

  it('hash/checksum-wrong branch does not leak the input key', function() {
    const bits = decode(validKey);
    bits[bits.length - 1] ^= 0xff;
    assertNoLeak(encode(bits), 'hash is wrong');
  });

  it('unexpected-key-length branch does not leak the input key', function() {
    const badKey = buildKeyWithRawLength(new Array(31).fill(1)); // ed25519 expects 32 bytes
    assertNoLeak(badKey, 'unexpected key length');
  });
});

describe('keystore AES-CTR IV and scrypt salt sizing', function() {
  this.timeout(20000);

  it('new keystores generate a 16-byte (128-bit) AES-CTR IV made of real single-byte elements', function(done) {
    const kp = new KeyPair('ed25519');
    keystore.encrypt(kp.getEncPrivateKey(), 'pw', function(encData) {
      expect(encData.iv.length).to.equal(16);
      expect(encData.iv.every((b) => b >= 0 && b <= 255)).to.equal(true);
      done();
    });
  });

  it('new keystores generate a 32-byte (256-bit) scrypt salt made of real single-byte elements', function(done) {
    const kp = new KeyPair('ed25519');
    keystore.encrypt(kp.getEncPrivateKey(), 'pw', function(encData) {
      expect(encData.salt.length).to.equal(32);
      expect(encData.salt.every((b) => b >= 0 && b <= 255)).to.equal(true);
      done();
    });
  });

  it('documents why salt must be a real byte array: vendored scrypt truncates each array element to its low byte', function(done) {
    // lib/vendor/scrypt.js's bytesToWords (Crypto-JS v2.5.4, line ~322) does
    // `(b[c] & 255)` on every array element -- it expects each element to
    // already be a single byte. Passing an sjcl-style bitArray (32-bit WORDS
    // per element, e.g. sjcl.random.randomWords(8)) through this silently
    // truncates every element to its low byte, collapsing an intended
    // 32-byte/256-bit salt down to just 8 *effective* bytes (64 bits) of
    // real entropy -- below NIST's 128-bit minimum. Proven here directly
    // against the vendored module: two salts that differ only in the upper
    // 24 bits of each 32-bit word derive the SAME key (the truncation
    // collapses them to the same effective bytes) -- this is the bug, and
    // legacy keystores already issued under it (word-array salt) rely on
    // this exact behavior being reproducible for decrypt, which is why the
    // fix is to generate NEW salts as real byte arrays rather than changing
    // the vendored scrypt itself.
    const scrypt = require('../lib/vendor/scrypt');
    const saltWords = [0x11223344, 0x55667788, 0x99aabbcc, 0xddeeff00, 0x12345678, 0x9abcdef0, 0x0f1e2d3c, 0x4b5a6978];
    const saltLowByteOnly = saltWords.map((w) => w & 0xff);

    scrypt.Crypto_scrypt('determinism-probe', saltWords, 16384, 8, 1, 32, function(dkA) {
      scrypt.Crypto_scrypt('determinism-probe', saltLowByteOnly, 16384, 8, 1, 32, function(dkB) {
        const hexA = scrypt.Crypto.util.bytesToHex(dkA);
        const hexB = scrypt.Crypto.util.bytesToHex(dkB);
        expect(hexA).to.equal(hexB); // pins the vendored module's truncate-to-low-byte behavior
        done();
      });
    });
  });

  it('a pre-existing oversized-IV/salt keystore (old format) still decrypts correctly -- no rotation required', function(done) {
    keystore.decrypt1(OLD_FORMAT_KEYSTORE, 'asd123456', function(result) {
      expect(result).to.equal(OLD_FORMAT_PLAINTEXT);
      done();
    });
  });

  it('a new keystore round-trips correctly through encrypt -> decrypt with the corrected IV/salt sizes', function(done) {
    const kp = new KeyPair('sm2');
    const priv = kp.getEncPrivateKey();
    keystore.encrypt(priv, 'roundtrip-pw', function(encData) {
      keystore.decrypt(encData, 'roundtrip-pw', function(result) {
        expect(result).to.equal(priv);
        done();
      });
    });
  });
});

describe('keystore does not log secret material to stdout', function() {
  this.timeout(20000);

  // Covers the five standard logging methods (not just console.log, the
  // exact one originally removed), so a regression using console.error/
  // warn/info/debug is caught too. Does NOT cover console.assert/count/
  // group/dir/table/trace or process.stdout/stderr.write -- see the
  // eslint rule's header comment / README.md for the full known-gap list.
  const CONSOLE_METHODS = ['log', 'error', 'warn', 'info', 'debug'];
  function withConsoleCapture(invoke, onDone) {
    const calls = [];
    const originals = {};
    CONSOLE_METHODS.forEach((m) => {
      originals[m] = console[m];
      console[m] = (...args) => calls.push(`console.${m}: ${args.join(' ')}`);
    });
    invoke(function(...cbArgs) {
      CONSOLE_METHODS.forEach((m) => { console[m] = originals[m]; });
      onDone(calls, ...cbArgs);
    });
  }

  it('encrypt() does not log to any console method', function(done) {
    const kp = new KeyPair('ed25519');
    withConsoleCapture(
      (cb) => keystore.encrypt(kp.getEncPrivateKey(), 'pw', cb),
      (calls) => { expect(calls).to.have.lengthOf(0); done(); },
    );
  });

  it('decrypt() does not log to any console method', function(done) {
    const kp = new KeyPair('ed25519');
    keystore.encrypt(kp.getEncPrivateKey(), 'pw', function(encData) {
      withConsoleCapture(
        (cb) => keystore.decrypt(encData, 'pw', cb),
        (calls) => { expect(calls).to.have.lengthOf(0); done(); },
      );
    });
  });

  it('decrypt1() does not log to any console method', function(done) {
    withConsoleCapture(
      (cb) => keystore.decrypt1(OLD_FORMAT_KEYSTORE, 'asd123456', cb),
      (calls) => { expect(calls).to.have.lengthOf(0); done(); },
    );
  });
});
